From 3bcd8f64a9f43a9edfda33a78f382ef6afb8f0d6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:11:08 +0100
Subject: [PATCH] applets/mediacontroller: change track with horizontal
 scrolling

Horizontal scrolling over the widget used to change the volume like the
vertical one. It now goes to the previous or next track, once per swipe
on a touchpad or once per notch on a tilting mouse wheel.

BUG: 460588
---
 .../mediacontroller/CompactRepresentation.qml | 25 ++++++++++++++++++-
 1 file changed, 24 insertions(+), 1 deletion(-)

diff --git a/applets/mediacontroller/CompactRepresentation.qml b/applets/mediacontroller/CompactRepresentation.qml
index e828b21696..c4f1349ced 100644
--- a/applets/mediacontroller/CompactRepresentation.qml
+++ b/applets/mediacontroller/CompactRepresentation.qml
@@ -77,11 +77,34 @@ Loader {
         acceptedButtons: Qt.LeftButton | Qt.MiddleButton | Qt.BackButton | Qt.ForwardButton
         hoverEnabled: compactRepresentation.item instanceof Kirigami.Icon
         property int wheelDelta: 0
+        property int horizontalWheelDelta: 0
+        // A touchpad swipe changes the track only once
+        property bool swiped: false
         onWheel: wheel => {
             if (mpris2Model.currentPlayer === null) {
                 return;
             }
-            wheelDelta += (wheel.inverted ? -1 : 1) * (wheel.angleDelta.y ? wheel.angleDelta.y : -wheel.angleDelta.x)
+            if (wheel.phase === Qt.ScrollBegin || wheel.phase === Qt.ScrollEnd) {
+                horizontalWheelDelta = 0;
+                swiped = false;
+            }
+            if (Math.abs(wheel.angleDelta.x) > Math.abs(wheel.angleDelta.y)) {
+                if (swiped) {
+                    return;
+                }
+                horizontalWheelDelta += (wheel.inverted ? -1 : 1) * wheel.angleDelta.x;
+                if (Math.abs(horizontalWheelDelta) >= 120) {
+                    if (horizontalWheelDelta > 0 && root.canGoPrevious) {
+                        root.previous();
+                    } else if (horizontalWheelDelta < 0 && root.canGoNext) {
+                        root.next();
+                    }
+                    horizontalWheelDelta = 0;
+                    swiped = wheel.phase !== Qt.NoScrollPhase;
+                }
+                return;
+            }
+            wheelDelta += (wheel.inverted ? -1 : 1) * wheel.angleDelta.y
             while (wheelDelta >= 120) {
                 wheelDelta -= 120;
                 mpris2Model.currentPlayer.changeVolume(root.volumePercentStep / 100, true);
-- 
